const item = $input.first().json;

// 5-Factor Weighted Score Model
const skillScore = 30;
const clientScore = 20;
const budgetScore = 20;
const clarityScore = 15;
const strategicScore = 10;

const totalScore = skillScore + clientScore + budgetScore + clarityScore + strategicScore;

return [{
  json: {
    ...item,
    totalScore,
    priority: totalScore >= 85 ? 'High Priority' : (totalScore >= 70 ? 'Worth Reviewing' : 'Low Priority')
  }
}];
